window.RP_SESSION={"id":"S-52bdfe838e84","messages":[{"id":"RP-0216543","time":"2026-08-06T22:54:00+09:00","room":"RP","name":"션 / 루체","profile":"델타인","identity":"reviewed","type":"dialogue","body":"무릇 북부인이라면 북부 말을 할 줄 알아야하는 법.","characters":["P-3bbc4a823df9","P-d8e7afee7c51"]},{"id":"RP-0216544","time":"2026-08-06T22:55:00+09:00","room":"RP","name":"션 / 루체","profile":"델타인","identity":"reviewed","type":"dialogue","body":"션이 요새 하는 일은 루체에게 북부 공용어와 헬그린두르의 말을 가르치는 것이었다.","characters":["P-3bbc4a823df9","P-d8e7afee7c51"]},{"id":"RP-0216545","time":"2026-08-06T22:56:00+09:00","room":"RP","name":"션 / 루체","profile":"델타인","identity":"reviewed","type":"dialogue","body":"책을 읽어줄 때, 헬그린두르의 머나먼 조상들이 배를 타고 다른 이들을 약탈하러 갔단 내용에서 눈을 말똥말똥하게 뜨는 것이 조금 걱정되긴 했지만…….","characters":["P-3bbc4a823df9","P-d8e7afee7c51"]},{"id":"RP-0216546","time":"2026-08-06T22:59:00+09:00","room":"RP","name":"션 / 루체","profile":"델타인","identity":"reviewed","type":"dialogue","body":"션의 필체는 다소 딱딱하지만 기품이 있다. 이는 파우스트 할망구가 말한 감상이니 나름 객관적일 것이다. \n\n그리고 은근히 북서쪽 지방의 사투리가 묻어난다고도 했다. 이 억양을 지우기 위해 레미 라다칼린, 그 미친 여자에게 교습을 받아야 했으니…….","characters":["P-3bbc4a823df9","P-d8e7afee7c51"]},{"id":"RP-0216547","time":"2026-08-06T23:06:00+09:00","room":"RP","name":"션 / 루체","profile":"델타인","identity":"reviewed","type":"dialogue","body":"루체를 올려놓은 허벅지가 저릿저릿할 때가 되어서야 오늘의 북부 말 가르치기 시간이 끝났다.","characters":["P-3bbc4a823df9","P-d8e7afee7c51"]},{"id":"RP-0216548","time":"2026-08-06T23:26:00+09:00","room":"RP","name":"션 / 루체","profile":"델타인","identity":"reviewed","type":"dialogue","body":"이야기가 끝나갈 때쯤에 루체는 배를 타고 싶다고 졸라댔다. 배라…….","characters":["P-3bbc4a823df9","P-d8e7afee7c51"]},{"id":"RP-0216549","time":"2026-08-06T23:26:00+09:00","room":"RP","name":"션 / 루체","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3bbc4a823df9","P-d8e7afee7c51"]},{"id":"RP-0216550","time":"2026-08-06T23:26:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
